@echo off
setlocal enabledelayedexpansion

:: Set source directory (change this)
set "source=C:\Users\YourName\Downloads"

cd /d "%source%"

:: Create folders if they don't exist
if not exist "Images" mkdir Images
if not exist "Videos" mkdir Videos
if not exist "Documents" mkdir Documents
if not exist "Archives" mkdir Archives

:: Move files by extension
for %%f in (*.jpg *.jpeg *.png *.gif *.bmp *.webp) do (
    move "%%f" "Images\" >nul 2>&1
)

for %%f in (*.mp4 *.avi *.mkv *.mov *.wmv) do (
    move "%%f" "Videos\" >nul 2>&1
)

for %%f in (*.pdf *.doc *.docx *.txt *.xlsx) do (
    move "%%f" "Documents\" >nul 2>&1
)

for %%f in (*.zip *.rar *.7z *.tar *.gz) do (
    move "%%f" "Archives\" >nul 2>&1
)

echo Files organized successfully!
pause

